import AppKit

/// What a step began with (spec §11 TU-8 (4)): the selection in time order,
/// every clip id, the range, and the selected clips' JSON for `changed`.
/// Taken from the window's edited project as the step begins. Main only.
struct TutorialBaseline {
    let selection: [UInt32]
    let clipIDs: Set<UInt32>
    let range: (start: Ticks, end: Ticks)?
    /// The clips selected at the start, as the core writes them, by id.
    let selectedClips: [UInt32: [String: Any]]

    init(document: ProjectDocument) {
        let edited = document.editedProject
        let snapshot = edited.snapshot
        let present = Set(snapshot.clips.map(\.id))
        selection = TutorialVariables.timeOrdered(
            Array(document.selection.intersection(present)), in: snapshot)
        clipIDs = present
        range = document.inOutRange
        let clips = TutorialWait.clipJSON(edited)
        var mine: [UInt32: [String: Any]] = [:]
        for id in selection { mine[id] = clips[id] }
        selectedClips = mine
    }
}

/// The latches a step clears as it begins: set by an event, read by a wait.
struct TutorialLatches {
    var exportStarted = false
    var playing = false
}

/// Whether a step's wait is met, and the needs sentence (spec §11 TU-8 (2),
/// (4)). Main only.
enum TutorialWait {
    // MARK: - Evaluation

    /// Whether every condition holds now.
    static func met(
        _ conditions: [TutorialCondition], baseline: TutorialBaseline, created: [UInt32],
        latches: TutorialLatches, document: ProjectDocument, window: NSWindow?
    ) -> Bool {
        guard !conditions.isEmpty else { return false }
        let edited = document.editedProject
        let snapshot = edited.snapshot
        return conditions.allSatisfy { condition in
            switch condition {
            case .selection(let low, let high, let filter):
                let clips = snapshot.clips.filter { document.selection.contains($0.id) }
                guard clips.count >= low, high.map({ clips.count <= $0 }) ?? true else {
                    return false
                }
                return clips.allSatisfy { TutorialClipFacts(clip: $0, in: snapshot).matches(filter) }
            case .changed(let paths):
                let now = clipJSON(edited)
                return baseline.selection.contains { id in
                    guard let before = baseline.selectedClips[id] else { return false }
                    let after = now[id] ?? [:]
                    return paths.contains { path in
                        !value(at: path, in: before).isEqual(value(at: path, in: after))
                    }
                }
            case .clips(let added, let kind):
                let fresh = snapshot.clips.filter {
                    !baseline.clipIDs.contains($0.id) && (kind == nil || $0.source.kindName == kind)
                }
                return fresh.count >= added
            case .playheadInside(let set):
                let ids = set == .selection ? baseline.selection : created
                let playhead = document.playhead
                return ids.contains { id in
                    guard let clip = snapshot.clip(id) else { return false }
                    return clip.start < playhead && playhead < clip.start + clip.duration
                }
            case .rangeSet:
                return document.inOutRange != nil
            case .rangeChanged(let edge):
                let now = document.inOutRange
                let before = baseline.range
                switch edge {
                case .start: return now?.start != before?.start
                case .end: return now?.end != before?.end
                }
            case .sheetExport:
                return window?.attachedSheet?.contentViewController is ExportSheetController
            case .exportStarted:
                return latches.exportStarted
            case .playing:
                return latches.playing
            }
        }
    }

    /// The value at a dotted path of a clip's JSON; absent is `NSNull`.
    static func value(at path: String, in clip: [String: Any]) -> NSObject {
        var here: Any = clip
        for part in path.split(separator: ".") {
            guard let object = here as? [String: Any], let next = object[String(part)] else {
                return NSNull()
            }
            here = next
        }
        return (here as? NSObject) ?? NSNull()
    }

    /// The last handle read and its clips by id: `changed` reads one handle
    /// many times between edits.
    private static var parsed: (handle: ReelProject, clips: [UInt32: [String: Any]])?

    /// The project's `clips`, as the core writes them, by id. Main only.
    static func clipJSON(_ project: ReelProject) -> [UInt32: [String: Any]] {
        if let parsed, parsed.handle === project { return parsed.clips }
        var clips: [UInt32: [String: Any]] = [:]
        if let top = (try? JSONSerialization.jsonObject(with: Data(project.json.utf8)))
            as? [String: Any], let list = top["clips"] as? [[String: Any]]
        {
            for clip in list {
                if let id = (clip["id"] as? NSNumber)?.uint32Value { clips[id] = clip }
            }
        }
        parsed = (project, clips)
        return clips
    }

    /// Lets go of the cached handle, so a closed document's project is not
    /// kept alive; a runner calls it as it goes. Main only.
    static func forgetClipJSON() {
        parsed = nil
    }

    // MARK: - Needs

    /// nil when some clip meets the tutorial's `needs.clip` (or it needs
    /// none); else the one sentence saying what is missing.
    static func needsSentence(_ needs: [String: Any]?, in snapshot: ProjectSnapshot) -> String? {
        guard let needs else { return nil }
        if snapshot.clips.contains(where: { TutorialClipFacts(clip: $0, in: snapshot).matches(needs) }) {
            return nil
        }
        var noun = "a clip"
        if let kind = needs["kind"] as? String {
            let article = ["a", "e", "i", "o", "u"].contains(kind.prefix(1)) ? "an" : "a"
            noun = "\(article) \(kind) clip"
        }
        let phrases: [String: (yes: String, no: String)] = [
            "has_sound": ("has sound", "has no sound"),
            "has_pixels": ("has a picture", "has no picture"),
            "follows_clip": (
                "meets the clip before it on its track",
                "does not meet the clip before it on its track"
            ),
            "has_transition": ("has a transition in", "has no transition in"),
        ]
        let predicates: [String] = TutorialClipFacts.keys.compactMap { key in
            guard let phrase = phrases[key], let wanted = needs[key] as? Bool else { return nil }
            return wanted ? phrase.yes : phrase.no
        }
        var sentence = "This tutorial needs " + noun
        if !predicates.isEmpty { sentence += " that " + joined(predicates) }
        return sentence + "."
    }

    /// `p`, `p1 and p2`, `p1, p2 and p3`.
    static func joined(_ parts: [String]) -> String {
        guard let last = parts.last else { return "" }
        guard parts.count > 1 else { return last }
        return parts.dropLast().joined(separator: ", ") + " and " + last
    }
}
import AppKit

/// A move the runner does not offer, in one sentence (spec §11 TU-8 (2), (6)).
struct TutorialRefusal: Error {
    let sentence: String
}

/// How a step was left: its wait met, Next, or Skip.
enum TutorialAdvance: String {
    case wait, next, skip
}

/// How a step was entered. A forward entry — start, Next, Skip, a met wait —
/// is a trigger; a Back entry is not (spec §11 TU-8 (3)).
enum TutorialEntry {
    case forward, back
}

/// What the last Show Me did (spec §11 TU-9).
struct TutorialShowMeOutcome {
    let step: Int
    let ok: Bool
    let error: String?
    /// Each call's result text, in order.
    let results: [String]
    /// The files an `export` call was sent to write.
    let paths: [String]
}

/// One tutorial running in one editor window, with no chrome (spec §11
/// TU-8): its needs checked at the start, each step's baseline and reveal as
/// it begins, its wait read after events, and Back, Skip, Next, Exit and Show
/// Me (`TutorialShowMe.swift`, TU-9). The panel that shows it is TU3's; the
/// dev tools (`AgentServer+Tutorials.swift`) drive it until then.
///
/// **Event-driven.** A committed document or view-state change
/// (`documentDidChange`, from the editor's `projectDidChange`), a playhead
/// move (`trigger`, from `inspectorPlayheadMoved`), a rate change, the
/// window's sheet beginning or ending, an export started and a forward step
/// entry each call `trigger()`, which schedules ONE coalesced evaluation on
/// the next main turn — a documented `DispatchQueue.main.async` seam — so the
/// event that met a wait has finished first. Nothing polls. While a Show Me
/// runs every evaluation is held, and one runs after its last entry.
///
/// Owned by `EditorViewController.tutorialRunner`; Exit sets that to nil and
/// undoes nothing, and closing the window ends it. Main only.
final class TutorialRunner {
    let tutorial: Tutorial
    weak var editor: EditorViewController?
    weak var document: ProjectDocument?

    /// The current step's index, 0-based; the last step's once finished.
    private(set) var index = 0
    private(set) var finished = false
    private var baseline: TutorialBaseline
    /// `$created` now: the ids added by the latest step, or Show Me call,
    /// that added any.
    var created: [UInt32] = []
    /// `created` as each step began, so Back restores it.
    private var createdAtBegin: [Int: [UInt32]] = [:]
    private var latches = TutorialLatches()
    private var revealRefused: String?
    private var completed: [(step: Int, by: TutorialAdvance)] = []
    private var evaluationPending = false
    private var observers: [NSObjectProtocol] = []

    // Show Me's state (`TutorialShowMe.swift`).
    /// True from the press until the last entry's answer is back.
    var showMeRunning = false
    /// A trigger arrived while a Show Me ran.
    var heldEvaluation = false
    /// The Show Me in flight; its generation drops a stale completion.
    var showMeRun: TutorialShowMeRun?
    var showMeGeneration = 0
    var lastShowMe: TutorialShowMeOutcome?

    private init(tutorial: Tutorial, editor: EditorViewController, document: ProjectDocument) {
        self.tutorial = tutorial
        self.editor = editor
        self.document = document
        baseline = TutorialBaseline(document: document)
    }

    deinit {
        for observer in observers { NotificationCenter.default.removeObserver(observer) }
        TutorialWait.forgetClipJSON()
    }

    // MARK: - Start and exit

    /// Starts `tutorial` in `editor`'s window, replacing any running there;
    /// refused, starting nothing, when its needs are unmet.
    @discardableResult
    static func start(_ tutorial: Tutorial, in editor: EditorViewController) throws
        -> TutorialRunner {
        guard let document = editor.document else {
            throw TutorialRefusal(sentence: "This window has no project.")
        }
        if let sentence = TutorialWait.needsSentence(
            tutorial.needs, in: document.editedProject.snapshot)
        {
            throw TutorialRefusal(sentence: sentence)
        }
        let runner = TutorialRunner(tutorial: tutorial, editor: editor, document: document)
        editor.tutorialRunner = runner
        runner.observeSheets(editor.view.window)
        runner.begin(0, .forward)
        return runner
    }

    /// Ends the tutorial; the project and its undo history stay as they are.
    func exit() {
        guard let editor, editor.tutorialRunner === self else { return }
        editor.tutorialRunner = nil
    }

    private func observeSheets(_ window: NSWindow?) {
        guard let window else { return }
        for name in [NSWindow.willBeginSheetNotification, NSWindow.didEndSheetNotification] {
            observers.append(
                NotificationCenter.default.addObserver(forName: name, object: window, queue: nil) {
                    [weak self] _ in self?.trigger()
                })
        }
    }

    // MARK: - Triggers

    /// Schedules one evaluation on the next main turn, or holds it while a
    /// Show Me runs.
    func trigger() {
        if showMeRunning {
            heldEvaluation = true
            return
        }
        guard !evaluationPending else { return }
        evaluationPending = true
        DispatchQueue.main.async { [weak self] in self?.evaluate() }
    }

        guard let tutorial = library.tutorial(id: id) else {
            throw ToolError(
                message: "No tutorial is called \(id); the tutorials are "
                    + library.ids.joined(separator: ", ") + ".")
        }
        do {
            try TutorialRunner.start(tutorial, in: editor)
        } catch let refusal as TutorialRefusal {
            throw ToolError(message: refusal.sentence)
        }
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialState(_ a: [String: Any]) throws -> String {
        let (editor, project) = try tutorialEditor(a)
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialExit(_ a: [String: Any]) throws -> String {
        let (editor, project) = try tutorialEditor(a)
        guard let runner = editor.tutorialRunner else {
            throw ToolError(message: Self.noTutorial)
        }
        runner.exit()
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialStep(_ a: [String: Any]) throws -> String {
        guard let action = try stringArg(a, "action") else {
            throw ToolError(message: "Missing required argument: action")
        }
        guard Self.tutorialActions.contains(action) else {
            throw ToolError(
                message: "action must be show_me, next, back or skip (got \"\(action)\").")
        }
        let (editor, project, runner) = try onMain {
            () throws -> (EditorViewController, Any, TutorialRunner) in
            let (editor, project) = try self.tutorialEditor(a)
            guard let runner = editor.tutorialRunner else {
                throw ToolError(message: Self.noTutorial)
            }
            do {
                switch action {
                case "show_me": try runner.showMe()
                case "next": try runner.next()
                case "back": try runner.back()
                default: try runner.skip()
                }
            } catch let refusal as TutorialRefusal {
                throw ToolError(message: refusal.sentence)
            }
            return (editor, project, runner)
        }
        if action == "show_me" {
            let started = Date()
            AgentLane.shared.releasingLock {
                while Date().timeIntervalSince(started) < Self.showMeTimeout {
                    let running = onMain { editor.tutorialRunner === runner && runner.showMeRunning }
                    guard running else { break }
                    Thread.sleep(forTimeInterval: 0.05)
                }
            }
        }
        return try jsonResult(onMain { Self.tutorialAnswer(editor, project) })
    }

    private static let tutorialActions: Set<String> = ["show_me", "next", "back", "skip"]
    private static let showMeTimeout = 60.0
    private static let noTutorial =
        "No tutorial is running in this window: tutorial_start starts one."

    /// The project's editor and its path for the answer, refused as
    /// `select_inspector_tab` refuses a windowless project. Main thread.
    private func tutorialEditor(_ a: [String: Any]) throws -> (EditorViewController, Any) {
        let document = try target(a)
        guard let editor = editor(document), editor.isViewLoaded else {
            let name = Self.path(of: document) ?? document.displayName ?? "Untitled"
            throw ToolError(
                message: "The project \(name) has no window: a tutorial runs only in its editor "
                    + "window.")
        }

