/// A move the runner does not offer, in one sentence (spec §11 TU-8 (2), (6)).
struct TutorialRefusal: Error {
    let sentence: String
}

/// How a step was left: its wait met, Next, or Skip.
enum TutorialAdvance: String {
    case wait, next, skip
}

/// How a step was entered. A forward entry — start, Next, Skip, a met wait —
/// is a trigger; a Back entry is not (spec §11 TU-8 (3)).
enum TutorialEntry {
    case forward, back
}

/// What the last Show Me did (spec §11 TU-9).
struct TutorialShowMeOutcome {
    let step: Int
    let ok: Bool
    let error: String?
    /// Each call's result text, in order.
    let results: [String]
    /// The files an `export` call was sent to write.
    let paths: [String]
}

/// One tutorial running in one editor window, with no chrome (spec §11
/// TU-8): its needs checked at the start, each step's baseline and reveal as
/// it begins, its wait read after events, and Back, Skip, Next, Exit and Show
/// Me (`TutorialShowMe.swift`, TU-9). The panel that shows it is TU3's; the
/// dev tools (`AgentServer+Tutorials.swift`) drive it until then.
///
/// **Event-driven.** A committed document or view-state change
/// (`documentDidChange`, from the editor's `projectDidChange`), a playhead
/// move (`trigger`, from `inspectorPlayheadMoved`), a rate change, the
/// window's sheet beginning or ending, an export started and a forward step
/// entry each call `trigger()`, which schedules ONE coalesced evaluation on
/// the next main turn — a documented `DispatchQueue.main.async` seam — so the
/// event that met a wait has finished first. Nothing polls. While a Show Me
/// runs every evaluation is held, and one runs after its last entry.
///
/// Owned by `EditorViewController.tutorialRunner`; Exit sets that to nil and
/// undoes nothing, and closing the window ends it. Main only.
final class TutorialRunner {
    let tutorial: Tutorial
    weak var editor: EditorViewController?
    weak var document: ProjectDocument?

    /// The current step's index, 0-based; the last step's once finished.
    private(set) var index = 0
    private(set) var finished = false
    private var baseline: TutorialBaseline
    /// `$created` now: the ids added by the latest step, or Show Me call,
    /// that added any.
    var created: [UInt32] = []
    /// `created` as each step began, so Back restores it.
    private var createdAtBegin: [Int: [UInt32]] = [:]
    private var latches = TutorialLatches()
    private var revealRefused: String?
    private var completed: [(step: Int, by: TutorialAdvance)] = []
    private var evaluationPending = false
    private var observers: [NSObjectProtocol] = []

    // Show Me's state (`TutorialShowMe.swift`).
    /// True from the press until the last entry's answer is back.
    var showMeRunning = false
    /// A trigger arrived while a Show Me ran.
    var heldEvaluation = false
    /// The Show Me in flight; its generation drops a stale completion.
    var showMeRun: TutorialShowMeRun?
    var showMeGeneration = 0
    var lastShowMe: TutorialShowMeOutcome?

    private init(tutorial: Tutorial, editor: EditorViewController, document: ProjectDocument) {
        self.tutorial = tutorial
        self.editor = editor
        self.document = document
        baseline = TutorialBaseline(document: document)
    }

    deinit {
        for observer in observers { NotificationCenter.default.removeObserver(observer) }
        TutorialWait.forgetClipJSON()
    }

    // MARK: - Start and exit

    /// Starts `tutorial` in `editor`'s window, replacing any running there;
    /// refused, starting nothing, when its needs are unmet.
    @discardableResult
    static func start(_ tutorial: Tutorial, in editor: EditorViewController) throws
        -> TutorialRunner {
        guard let document = editor.document else {
            throw TutorialRefusal(sentence: "This window has no project.")
        }
        if let sentence = TutorialWait.needsSentence(
            tutorial.needs, in: document.editedProject.snapshot)
        {
            throw TutorialRefusal(sentence: sentence)
        }
        let runner = TutorialRunner(tutorial: tutorial, editor: editor, document: document)
        editor.tutorialRunner = runner
        runner.observeSheets(editor.view.window)
        runner.begin(0, .forward)
        return runner
    }

    /// Ends the tutorial; the project and its undo history stay as they are.
    func exit() {
        guard let editor, editor.tutorialRunner === self else { return }
        editor.tutorialRunner = nil
    }

    private func observeSheets(_ window: NSWindow?) {
        guard let window else { return }
        for name in [NSWindow.willBeginSheetNotification, NSWindow.didEndSheetNotification] {
            observers.append(
                NotificationCenter.default.addObserver(forName: name, object: window, queue: nil) {
                    [weak self] _ in self?.trigger()
                })
        }
    }

    // MARK: - Triggers

    /// Schedules one evaluation on the next main turn, or holds it while a
    /// Show Me runs.
    func trigger() {
        if showMeRunning {
            heldEvaluation = true
            return
        }
        guard !evaluationPending else { return }
        evaluationPending = true
        DispatchQueue.main.async { [weak self] in self?.evaluate() }
    }

